#include <stdio.h>
int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 1;
    FILE *f = fopen("so.txt", "w");
    if (f == NULL) return 1;
    for (int i = 1; i <= n; i++) fprintf(f, "%d\n", i);
    fclose(f);
    f = fopen("so.txt", "r");
    if (f == NULL) return 1;
    int x, tong = 0;
    while (fscanf(f, "%d", &x) == 1) tong += x;
    fclose(f);
    printf("%d\n", tong);
    return 0;
}
